import{_ as e,o as a,c as i,a3 as r}from"./chunks/framework.Zs2ruvLs.js";const y=JSON.parse('{"title":"@frank/crypto-box","description":"","frontmatter":{},"headers":[],"relativePath":"sdks/crypto-box.md","filePath":"sdks/crypto-box.md","lastUpdated":1791334697000}'),l={name:"sdks/crypto-box.md"};function o(n,t,s,c,d,p){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="frank-crypto-box" tabindex="-1">@frank/crypto-box <a class="header-anchor" href="#frank-crypto-box" aria-label="Permalink to &quot;@frank/crypto-box&quot;">​</a></h1><p><strong>Versioned Deniable AEAD Encryption &amp; Key Encapsulation (HPKE)</strong><br><strong>Package Path</strong>: <code>packages/crypto-box</code><br><strong>License</strong>: MIT</p><hr><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><code>@frank/crypto-box</code> implements high-assurance, versioned, deniable public-key encryption using Hybrid Public Key Encryption (HPKE, RFC 9180) principles tailored for secp256k1.</p><p>It provides authenticated and unauthenticated encryption modes using XChaCha20-Poly1305 and AES-256-GCM.</p><hr><h2 id="_2-cipher-suites" tabindex="-1">2. Cipher Suites <a class="header-anchor" href="#_2-cipher-suites" aria-label="Permalink to &quot;2. Cipher Suites&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Suite ID</th><th style="text-align:left;">Name</th><th style="text-align:left;">Mode</th><th style="text-align:left;">KEM</th><th style="text-align:left;">AEAD</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>1</code></strong></td><td style="text-align:left;"><strong>auth-xchacha20-poly1305</strong></td><td style="text-align:left;"><strong>Auth</strong></td><td style="text-align:left;"><strong>DHKEM(secp256k1, HKDF-SHA256)</strong></td><td style="text-align:left;"><strong>XChaCha20-Poly1305</strong></td></tr><tr><td style="text-align:left;"><code>0xFE01</code></td><td style="text-align:left;">base-aes-256-gcm</td><td style="text-align:left;">Base</td><td style="text-align:left;">DHKEM(secp256k1, HKDF-SHA256)</td><td style="text-align:left;">AES-256-GCM</td></tr><tr><td style="text-align:left;"><code>0xFE02</code></td><td style="text-align:left;">base-xchacha20-poly1305</td><td style="text-align:left;">Base</td><td style="text-align:left;">DHKEM(secp256k1, HKDF-SHA256)</td><td style="text-align:left;">XChaCha20-Poly1305</td></tr><tr><td style="text-align:left;"><code>0xFE03</code></td><td style="text-align:left;">auth-aes-256-gcm</td><td style="text-align:left;">Auth</td><td style="text-align:left;">DHKEM(secp256k1, HKDF-SHA256)</td><td style="text-align:left;">AES-256-GCM</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Suite <code>1</code> (<code>auth-xchacha20-poly1305</code>) is the designated production encryption suite for Type 5 Direct Message payloads in Frank CBOR v1.</p></div><hr><h2 id="_3-cryptographic-properties" tabindex="-1">3. Cryptographic Properties <a class="header-anchor" href="#_3-cryptographic-properties" aria-label="Permalink to &quot;3. Cryptographic Properties&quot;">​</a></h2><ol><li><strong>Cryptographic Deniability</strong>: Authentication is achieved exclusively through Diffie-Hellman derived symmetric keys. Because the recipient can mathematically produce identical ciphertexts using their own private key and the sender&#39;s public key, the ciphertext cannot serve as transferable proof of authorship to a third party.</li><li><strong>Deterministic CBOR Envelope (v2)</strong>: Sealed envelopes serialize as canonical CBOR maps containing version, suite ID, KEM ID, a 32-byte fresh salt, an ephemeral encapsulated public key point, and the ciphertext.</li><li><strong>Associated Data Binding</strong>: AEAD encryption tightly binds caller context, sender public key, and recipient public key, preventing ciphertext transplantation attacks.</li></ol>',13)])])}const g=e(l,[["render",o]]);export{y as __pageData,g as default};
